// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address newOwner) public {
        // owner is initially address(0), which is the only authorized caller;
        // vm.prank is allowed, so drive transferOwnership from address(0).
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // General rule: after transferOwnership(a) by the current owner, owner == a.
        assertTrue(c.owner() == newOwner);
    }
}
